-- Portable SQL (H2 / PostgreSQL). Identity columns use the SQL-standard
-- "GENERATED BY DEFAULT AS IDENTITY"; MySQL will need a vendor-specific migration.

CREATE TABLE candidate (
    id                 BIGINT GENERATED BY DEFAULT AS IDENTITY,
    first_name         VARCHAR(100)             NOT NULL,
    last_name          VARCHAR(100)             NOT NULL,
    email              VARCHAR(254)             NOT NULL,
    phone              VARCHAR(30),
    current_title      VARCHAR(150),
    current_company    VARCHAR(150),
    location           VARCHAR(150),
    experience_years   DECIMAL(4, 1),
    notice_period_days INTEGER,
    status             VARCHAR(20)              DEFAULT 'NEW' NOT NULL,
    notes              VARCHAR(4000),
    created_at         TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at         TIMESTAMP WITH TIME ZONE NOT NULL,
    version            BIGINT                   DEFAULT 0 NOT NULL,
    deleted            BOOLEAN                  DEFAULT FALSE NOT NULL,
    CONSTRAINT pk_candidate PRIMARY KEY (id),
    CONSTRAINT uq_candidate_email UNIQUE (email),
    CONSTRAINT ck_candidate_experience_years CHECK (experience_years >= 0),
    CONSTRAINT ck_candidate_notice_period_days CHECK (notice_period_days >= 0)
    -- TODO: restore CHECK (status IN ('NEW','SCREENING','INTERVIEWING','OFFERED','HIRED','REJECTED'))
    -- once H2 ships the fix for https://github.com/h2database/h2database/issues/4063.
    -- In H2 <= 2.4.240 such a CHECK (also as an OR chain, which H2 rewrites to IN) keeps a
    -- reference to the session that created it (Flyway's); once that connection closes, every
    -- insert fails with "Check constraint invalid ... database has been closed".
    -- Until then, valid values are enforced by CandidateStatus + @Enumerated(EnumType.STRING).
);

CREATE INDEX idx_candidate_last_name ON candidate (last_name);
CREATE INDEX idx_candidate_status ON candidate (status);
CREATE INDEX idx_candidate_location ON candidate (location);
CREATE INDEX idx_candidate_experience_years ON candidate (experience_years);

CREATE TABLE skill (
    id   BIGINT GENERATED BY DEFAULT AS IDENTITY,
    name VARCHAR(100) NOT NULL,
    CONSTRAINT pk_skill PRIMARY KEY (id),
    CONSTRAINT uq_skill_name UNIQUE (name)
);

CREATE TABLE candidate_skill (
    candidate_id BIGINT NOT NULL,
    skill_id     BIGINT NOT NULL,
    CONSTRAINT pk_candidate_skill PRIMARY KEY (candidate_id, skill_id),
    CONSTRAINT fk_candidate_skill_candidate FOREIGN KEY (candidate_id) REFERENCES candidate (id),
    CONSTRAINT fk_candidate_skill_skill FOREIGN KEY (skill_id) REFERENCES skill (id)
);

CREATE INDEX idx_candidate_skill_skill_id ON candidate_skill (skill_id);
